using CarCareTracker.External.Interfaces;
using CarCareTracker.Models;
using Npgsql;
using System.Text.Json;

namespace CarCareTracker.External.Implementations
{
    public class PGAssistantDataAccess : IAssistantDataAccess
    {
        private NpgsqlDataSource pgDataSource;
        private readonly ILogger<PGAssistantDataAccess> _logger;
        private static string tableName = "assistant_messages";
        public PGAssistantDataAccess(IConfiguration config, ILogger<PGAssistantDataAccess> logger)
        {
            pgDataSource = NpgsqlDataSource.Create(config["POSTGRES_CONNECTION"] ?? string.Empty);
            _logger = logger;
            try
            {
                string initCMD = $"CREATE SCHEMA IF NOT EXISTS app; " +
                    $"CREATE TABLE IF NOT EXISTS app.{tableName} (id INT GENERATED BY DEFAULT AS IDENTITY primary key, userId INT not null, createdAt TIMESTAMPTZ not null, data jsonb not null); " +
                    $"CREATE INDEX IF NOT EXISTS {tableName}_user_idx ON app.{tableName} (userId, id); " +
                    $"CREATE INDEX IF NOT EXISTS {tableName}_created_idx ON app.{tableName} (createdAt)";
                using (var ctext = pgDataSource.CreateCommand(initCMD))
                {
                    ctext.ExecuteNonQuery();
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex.Message);
            }
        }
        public int Add(AssistantMessage message)
        {
            try
            {
                using (var ctext = pgDataSource.CreateCommand($"INSERT INTO app.{tableName} (userId, createdAt, data) VALUES(@userId, @createdAt, CAST(@data AS jsonb)) RETURNING id"))
                {
                    ctext.Parameters.AddWithValue("userId", message.UserId);
                    ctext.Parameters.AddWithValue("createdAt", DateTime.SpecifyKind(message.CreatedAtUtc, DateTimeKind.Utc));
                    ctext.Parameters.AddWithValue("data", "{}");
                    message.Id = Convert.ToInt32(ctext.ExecuteScalar());
                }
                using (var ctext = pgDataSource.CreateCommand($"UPDATE app.{tableName} SET data = CAST(@data AS jsonb) WHERE id = @id"))
                {
                    ctext.Parameters.AddWithValue("id", message.Id);
                    ctext.Parameters.AddWithValue("data", JsonSerializer.Serialize(message));
                    ctext.ExecuteNonQuery();
                }
                return message.Id;
            }
            catch (Exception ex)
            {
                _logger.LogError(ex.Message);
                return 0;
            }
        }
        public List<AssistantMessage> GetPage(int userId, int beforeId, int limit)
        {
            var results = new List<AssistantMessage>();
            try
            {
                var filter = beforeId > 0 ? " AND id < @beforeId" : string.Empty;
                using (var ctext = pgDataSource.CreateCommand($"SELECT data FROM app.{tableName} WHERE userId = @userId{filter} ORDER BY id DESC LIMIT @limit"))
                {
                    ctext.Parameters.AddWithValue("userId", userId);
                    ctext.Parameters.AddWithValue("beforeId", beforeId);
                    ctext.Parameters.AddWithValue("limit", limit);
                    using (NpgsqlDataReader reader = ctext.ExecuteReader())
                        while (reader.Read())
                        {
                            var message = JsonSerializer.Deserialize<AssistantMessage>(reader["data"] as string ?? "{}");
                            if (message != null)
                            {
                                results.Add(message);
                            }
                        }
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex.Message);
            }
            return results;
        }
        private int Delete(string where, Action<NpgsqlCommand> parameters)
        {
            try
            {
                using (var ctext = pgDataSource.CreateCommand($"DELETE FROM app.{tableName} WHERE {where}"))
                {
                    parameters(ctext);
                    return ctext.ExecuteNonQuery();
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex.Message);
                return 0;
            }
        }
        public int DeleteAll(int userId)
        {
            return Delete("userId = @userId", x => x.Parameters.AddWithValue("userId", userId));
        }
        public int DeleteOlderThan(DateTime cutoffUtc)
        {
            return Delete("createdAt < @cutoff", x => x.Parameters.AddWithValue("cutoff", DateTime.SpecifyKind(cutoffUtc, DateTimeKind.Utc)));
        }
    }
}
